    bg = max(counts, key=counts.get)

    # Find 4-connected foreground components.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc, grid[rr][cc]))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] != bg and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            components.append(comp)

    if not components:
        return [row[:] for row in grid]

    # The largest connected foreground object is the pattern.
    pattern = max(components, key=len)
    pattern_cells = {(r, c) for r, c, _ in pattern}

    # Use the 1 in the pattern as its anchor when present; otherwise use
    # the center of the pattern's bounding box.
    ones = [(r, c) for r, c, v in pattern if v == 1]
    if ones:
        anchor_r, anchor_c = ones[0]
    else:
        min_r = min(r for r, c, _ in pattern)
        max_r = max(r for r, c, _ in pattern)
        min_c = min(c for r, c, _ in pattern)
        max_c = max(c for r, c, _ in pattern)
        anchor_r = (min_r + max_r) // 2
        anchor_c = (min_c + max_c) // 2

    # The separate foreground color(s) mark locations for the pattern.
    outside = [
        (r, c, grid[r][c])
        for r in range(h) for c in range(w)
        if grid[r][c] != bg and (r, c) not in pattern_cells
    ]
    if not outside:
        return [row[:] for row in grid]

    target_color = max(
        set(v for _, _, v in outside),
