    # Group foreground cells, including diagonal neighbors. The original
    # pattern is the largest such connected component.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc, grid[rr][cc]))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = rr + dr, cc + dc
                        if (0 <= nr < h and 0 <= nc < w
                                and grid[nr][nc] != bg
                                and (nr, nc) not in seen):
                            seen.add((nr, nc))
                            stack.append((nr, nc))
            components.append(comp)

    if not components:
        return [row[:] for row in grid]

    pattern = max(components, key=len)
    pattern_positions = {(r, c) for r, c, _ in pattern}

    min_r = min(r for r, c, _ in pattern)
    max_r = max(r for r, c, _ in pattern)
    min_c = min(c for r, c, _ in pattern)
    max_c = max(c for r, c, _ in pattern)
    anchor_r = (min_r + max_r) // 2
    anchor_c = (min_c + max_c) // 2

    # Foreground cells outside the original pattern mark copy locations.
    targets = [
        (r, c)
        for r in range(h) for c in range(w)
        if grid[r][c] != bg and (r, c) not in pattern_positions
    ]

    out = [row[:] for row in grid]
    for tr, tc in targets:
        for r, c, value in pattern:
            rr = tr + r - anchor_r
            cc = tc + c - anchor_c
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value

    return out
